INSERT INTO table3 (c14, c56, c20, c21, c49, c30, c23, c24, c35) VALUES ('Z001', 'dummy56', 'dummy20', 'dummy21', 'Q1_result', 'Q1_result', 'dummy23', 'dummy24', '2023-01-01');
INSERT INTO table2 (c13, c50, c29, c47, c12) VALUES ('Z001', 'dummy50', 1, 1, 10);

-- Now insert 333 rows with keys 'A001' ... 'A333' in alphabetical order.
-- (When sorted lexicographically, 'A001' comes before 'A002' etc., but note that physically they are inserted after 'Z001'.)

INSERT INTO table3 (c14, c56, c20, c21, c49, c30, c23, c24, c35) VALUES ('A001', 'dummy56', 'dummy20', 'dummy21', 'Subq_A001', 'Subq_A001', 'dummy23', 'dummy24', '2023-01-01');
