-- There is no counterexample since for every database instance (adhering to the schema and constraints) the two queries produce the same result.
-- For example, consider the following test data which yields the same output in Q1 and Q2:

INSERT INTO table7 (c14, c18) VALUES (101, 'Marvel Comics');

INSERT INTO table9 (c14, c10, c7, c11, c21, c20, c17, c2) VALUES (1, 10, 20, 30, 40, 50, 101, 1);
INSERT INTO table9 (c14, c10, c7, c11, c21, c20, c17, c2) VALUES (2, 11, 21, 31, 41, 51, 101, 2);

INSERT INTO table6 (c13, c15) VALUES (1, 201);
INSERT INTO table6 (c13, c15) VALUES (1, 201);  -- duplicate row for testing join multiplicity
INSERT INTO table6 (c13, c15) VALUES (2, 202);

INSERT INTO table10 (c14, c16) VALUES (201, 'Super Strength');
INSERT INTO table10 (c14, c16) VALUES (202, 'X-ray Vision');

-- When these rows are joined, the final join result is identical for Q1 and Q2; therefore both queries yield the same percentage.
-- Since no test data can be produced where Q1 and Q2 differ, the counterexample is empty.

